result: write_file({"path": "src/slugify.js", "content": "export function slugify(text) {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
}
"})
write_file({"path": "test/slugify.test.js", "content": "import assert from 'node:assert/strict';
import { slugify } from '../src/slugify.js';

// Basic lowercasing
assert.equal(slugify('Hello World'), 'hello-world');

// Multiple non-alphanumeric chars collapse to one hyphen
assert.equal(slugify('Hello,   World!'), 'hello-world');

// Leading/trailing hyphens stripped
assert.equal(slugify('  Hello  '), 'hello');
assert.equal(slugify('--Hello--'), 'hello');

// Mixed punctuation
assert.equal(slugify('Foo & Bar'), 'foo-bar');
assert.equal(slugify('a.b.c'), 'a-b-c');

// Digits preserved
assert.equal(slugify('Item 42'), 'item-42');

// Empty / all-punctuation
assert.equal(slugify('!!!'), '');
assert.equal(slugify(''), '');

// Unicode non-alphanumeric treated as separator
assert.equal(slugify('café crème'), 'caf-crème'.replace(/[^a-z0-9-]/g, '-').replace(/-+/g, '-'));

console.log('All slugify tests passed.');
"})

